#include <cstdio>
#include <iostream>
using namespace std;
typedef long long ll;
const int MOD=1e9+7;

struct Mat {
    int mat[33][33];
} identity, matrices[70], answer, pre[70], suf[70];

ll N, K;

void printMat(const Mat &x){
    for(int i=0; i<=K; i++){
        for(int j=0; j<=K; j++)
            cout << x.mat[i][j] << ' ';
        cout << endl;
    }
    cout << endl;
}

Mat multiplyMat(const Mat &A, const Mat &B){
    Mat C=identity;
    for(int k=0; k<=K; k++){
        for(int i=0; i<=K; i++){
            for(int j=0; j<=K; j++){
                ll val = ((ll)A.mat[i][k] * B.mat[k][j]) % MOD;
                C.mat[i][j] = (C.mat[i][j] + val) % MOD;
            }
        }
    }
    return C;
}

void computePrefixSuffix(){
    int i;
    pre[0] = matrices[0];
    for(i=1; i<K; i++)
        pre[i] = multiplyMat(pre[i-1], matrices[i]);
    suf[K-1] = matrices[K-1];
    for(i=K-2; i>=0; i--)
        suf[i] = multiplyMat(matrices[i], suf[i+1]);
    matrices[0] = suf[0];
    for(i=1; i<K; i++)
        matrices[i] = multiplyMat(suf[i], pre[i-1]);
}

void runProgram(){
    cin >> N >> K;
    int i, j;
    answer = identity;
    for(i=0; i<K; i++){
        matrices[i] = identity;
        for(j=0; j<=K; j++)
            matrices[i].mat[j][j] = 1;
        for(j=0; j<=K; j++)
            matrices[i].mat[j][i] = 1;
        answer.mat[i][i] = 1;
    }
    answer.mat[K][K] = 1;
    while(N > 0){
        int t = N % K;
        if(t != 0){
            ll pos=0, tmp=N;
            while(tmp){
                tmp /= K;
                pos = (pos + tmp) % K;
            }
            for(i=t-1; i>=0; i--){
                answer = multiplyMat(matrices[(pos + i) % K], answer);
            }
        }
        computePrefixSuffix();
        N /= K;
    }
    int res=1;
    for(i=0; i<K; i++)
        res = (res + answer.mat[K][i]) % MOD;
    cout << res << endl;
}

int main(){
    runProgram();
    return 0;
}
